  1	package hotel.reservations;
  2	
  3	import hotel.rooms.Room;
  4	import hotel.rooms.RoomType;
  5	import java.math.BigDecimal;
  6	import java.time.DayOfWeek;
  7	import java.time.LocalDate;
  8	import java.time.temporal.ChronoUnit;
  9	import java.util.Map;
 10	
 11	import static hotel.reservations.PriceCalculator.cents;
 12	
 13	/**
 14	 * All rate-plan-specific rules in one place: who may book, how the price is built, and what comes
 15	 * back on cancellation. Adding a new plan touches only this class and the RatePlan enum.
 16	 */
 17	public final class RatePlanRules {
 18	
 19	    static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
 20	            "TECNOSUL", new BigDecimal("0.12"),
 21	            "AGROVALE", new BigDecimal("0.18"),
 22	            "FARMAVIDA", new BigDecimal("0.25"));
 23	
 24	    static final Map<RoomType, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
 25	            RoomType.STANDARD, new BigDecimal("520.00"),
 26	            RoomType.DELUXE, new BigDecimal("820.00"),
 27	            RoomType.SUITE, new BigDecimal("1200.00"));
 28	
 29	    private RatePlanRules() {}
 30	
 31	    /** Throws INVALID_REQUEST if the reservation cannot be made under the given plan. */
 32	    public static void validate(
 33	            RatePlan ratePlan, Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
 34	        switch (ratePlan) {
 35	            case CORPORATE -> {
 36	                if (companyCode == null || !CORPORATE_DISCOUNTS.containsKey(companyCode)) {
 37	                    throw new HotelException(
 38	                            ErrorCode.INVALID_REQUEST,
 39	                            "a valid company code is required for the CORPORATE rate plan");
 40	                }
 41	            }
 42	            case WEEKEND_PACKAGE -> {
 43	                boolean startsOnFriday = checkIn.getDayOfWeek() == DayOfWeek.FRIDAY;
 44	                boolean exactlyTwoNights = ChronoUnit.DAYS.between(checkIn, checkOut) == 2;
 45	                if (!startsOnFriday || !exactlyTwoNights) {
 46	                    throw new HotelException(
 47	                            ErrorCode.INVALID_REQUEST,
 48	                            "WEEKEND_PACKAGE requires check-in on Friday and check-out on Sunday (2 nights)");
 49	                }
 50	            }
 51	            case LONG_STAY -> {
 52	                long nights = ChronoUnit.DAYS.between(checkIn, checkOut);
 53	                if (nights < 7) {
 54	                    throw new HotelException(
 55	                            ErrorCode.INVALID_REQUEST,
 56	                            "LONG_STAY requires at least 7 nights");
 57	                }
 58	            }
 59	            default -> {}
 60	        }
 61	    }
 62	
 63	    /**
 64	     * Fixed price for WEEKEND_PACKAGE, or null for plans that use the normal per-night subtotal.
 65	     * When non-null, PriceCalculator skips the per-night loop and uses this price directly.
 66	     */
 67	    public static BigDecimal weekendPackagePrice(RoomType roomType) {
 68	        return WEEKEND_PACKAGE_PRICES.get(roomType);
 69	    }
 70	
 71	    /** Discount amount to subtract from the subtotal; zero for plans without a discount. */
 72	    public static BigDecimal discount(RatePlan ratePlan, BigDecimal subtotal, String companyCode) {
 73	        return switch (ratePlan) {
 74	            case STANDARD, WEEKEND_PACKAGE -> cents(BigDecimal.ZERO);
 75	            case NON_REFUNDABLE -> cents(subtotal.multiply(new BigDecimal("0.15")));
 76	            case CORPORATE -> cents(subtotal.multiply(CORPORATE_DISCOUNTS.get(companyCode)));
 77	            case LONG_STAY -> cents(subtotal.multiply(new BigDecimal("0.10")));
 78	        };
 79	    }
 80	
 81	    /** Refund amount for a paid reservation being cancelled. */
 82	    public static BigDecimal refund(RatePlan ratePlan, BigDecimal amountPaid) {
 83	        return switch (ratePlan) {
 84	            case STANDARD, CORPORATE, LONG_STAY -> amountPaid;
 85	            case NON_REFUNDABLE -> cents(BigDecimal.ZERO);
 86	            case WEEKEND_PACKAGE -> cents(amountPaid.divide(new BigDecimal("2")));
 87	        };
 88	    }
 89	}
 90	package hotel.reservations;
 91	
 92	public enum RatePlan {
 93	    /** Full price; the guest gets everything back when cancelling a confirmed reservation. */
 94	    STANDARD,
 95	    /** 15% off, but nothing comes back on cancellation. */
 96	    NON_REFUNDABLE,
 97	    /** Corporate discount by company code; full refund on cancellation. */
 98	    CORPORATE,
 99	    /** Fixed weekend package price (Fri–Sun); half refund on cancellation. */
100	    WEEKEND_PACKAGE,
101	    /** 7+ nights, 10% off; full refund on cancellation. */
102	    LONG_STAY
103	}
104	package hotel.reservations;
105	
106	import hotel.rooms.Room;
107	import java.math.BigDecimal;
108	import java.math.RoundingMode;
109	import java.time.LocalDate;
110	import java.time.Month;
111	
112	/**
113	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
114	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
115	 * (half-even) at every step.
116	 */
117	public final class PriceCalculator {
118	
119	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
120	
121	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
122	        if (ratePlan == RatePlan.WEEKEND_PACKAGE) {
123	            BigDecimal packagePrice = RatePlanRules.weekendPackagePrice(room.type());
124	            return new Price(2, packagePrice, cents(BigDecimal.ZERO), packagePrice);
125	        }
126	        int nights = 0;
127	        BigDecimal subtotal = cents(BigDecimal.ZERO);
128	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
129	            subtotal = subtotal.add(nightPrice(room, night));
130	            nights++;
131	        }
132	        BigDecimal discount = RatePlanRules.discount(ratePlan, subtotal, companyCode);
133	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
134	    }
135	
136	    BigDecimal nightPrice(Room room, LocalDate night) {
137	        BigDecimal nightlyRate = room.nightlyRate();
138	        if (isHighSeason(night)) {
139	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
140	        }
141	        return cents(nightlyRate);
142	    }
143	
144	    /** High season: from December 15 to the end of February, and the whole of July. */
145	    static boolean isHighSeason(LocalDate date) {
146	        Month month = date.getMonth();
147	        return month == Month.JANUARY
148	                || month == Month.FEBRUARY
149	                || month == Month.JULY
150	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
151	    }
152	
153	    static BigDecimal cents(BigDecimal value) {
154	        return value.setScale(2, RoundingMode.HALF_EVEN);
155	    }
156	}
157	package hotel.reservations;
158	
159	import hotel.documents.ReservationReceipt;
160	import hotel.messages.EmailSender;
161	import hotel.rooms.Room;
162	import hotel.rooms.Rooms;
163	import java.math.BigDecimal;
164	
165	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
166	public final class ReservationService {
167	
168	    static final String HOTEL_NAME = "Pousada Maré Alta";
169	
170	    private final Rooms rooms;
171	    private final ReservationStore store;
172	    private final PriceCalculator priceCalculator;
173	    private final EmailSender emailSender;
174	
175	    public ReservationService(
176	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
177	        this.rooms = rooms;
178	        this.store = store;
179	        this.priceCalculator = priceCalculator;
180	        this.emailSender = emailSender;
181	    }
182	
183	    public synchronized Reservation create(NewReservation request) {
184	        if (!request.checkOut().isAfter(request.checkIn())) {
185	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
186	        }
187	        if (request.guests() < 1) {
188	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
189	        }
190	        Room room = rooms.find(request.roomNumber())
191	                .orElseThrow(() -> new HotelException(
192	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
193	        if (request.guests() > room.capacity()) {
194	            throw new HotelException(
195	                    ErrorCode.CAPACITY_EXCEEDED,
196	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
197	        }
198	        boolean roomTaken = store.all().stream()
199	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
200	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
201	        if (roomTaken) {
202	            throw new HotelException(
203	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
204	        }
205	        RatePlanRules.validate(request.ratePlan(), room, request.checkIn(), request.checkOut(), request.companyCode());
206	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
207	        Reservation reservation = new Reservation(store.nextId(), request, price);
208	        store.save(reservation);
209	        return reservation;
210	    }
211	
212	    public Reservation find(long reservationId) {
213	        return store.find(reservationId)
214	                .orElseThrow(() -> new HotelException(
215	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
216	    }
217	
218	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
219	    public synchronized Reservation confirm(long reservationId) {
220	        Reservation reservation = find(reservationId);
221	        if (reservation.status() != ReservationStatus.PENDING) {
222	            throw notAllowed(reservation, "confirm");
223	        }
224	        reservation.confirmPayment();
225	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
226	        emailSender.send(
